class ApiError(Exception):
    """An error the client is allowed to see, with a stable code."""

    def __init__(self, code, message, status=400):
        super().__init__(message)
        self.code = code
        self.message = message
        self.status = status

    def as_dict(self):
        return {"code": self.code, "message": self.message, "status": self.status}


def now():
    return datetime.now(timezone.utc)


def iso(value=None):
    value = value or now()
    if isinstance(value, str):
        return value
    return value.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def parse_dt(value):
    if not value:
        return None
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    try:
        text = str(value).replace("Z", "+00:00")
        parsed = datetime.fromisoformat(text)
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def sqlq(value):
    """Safely embed a value as a SQL literal (shared tables, no bound params in
    pod.query). Ids are validated as UUIDs first; free text has quotes doubled
    and backslashes stripped."""
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, (int, float)):
        return str(value)
    text = str(value).replace("\\", "").replace("'", "''")
    return "'" + text + "'"


UUID_RE = re.compile(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")


def is_uuid(value):
    return bool(value) and bool(UUID_RE.match(str(value)))


def require_uuid(value, field="id"):
    if not is_uuid(value):
        raise ApiError("invalid_id", f"{field} must be a valid id.", 422)
    return str(value)


def clean_text(value, field, max_length, required=False, min_length=1):
    text = "" if value is None else str(value).strip()
    if not text:
        if required:
            raise ApiError("invalid_input", f"{field} is required.", 422)
        return ""
    if len(text) < min_length:
        raise ApiError("invalid_input", f"{field} is too short.", 422)
    if len(text) > max_length:
        raise ApiError("invalid_input", f"{field} must be at most {max_length} characters.", 422)
    return text


EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$")


def clean_email(value):
    email = str(value or "").strip().lower()
    if not EMAIL_RE.match(email):
        raise ApiError("invalid_email", "Enter a valid email address.", 422)
    return email


# ------------------------------------------------------------------ passwords

def hash_password(password, salt=None):
    salt = salt or secrets.token_hex(16)
    digest = hashlib.scrypt(password.encode("utf-8"), salt=salt.encode("utf-8"),
                            n=2 ** 14, r=8, p=1, dklen=32)
    return digest.hex(), salt


def verify_password(password, stored_hash, salt):
    if not stored_hash or not salt:
        return False
    candidate, _ = hash_password(password, salt)
    return hmac.compare_digest(candidate, str(stored_hash))


def validate_password(password):
    if not isinstance(password, str) or len(password) < MIN_PASSWORD_LENGTH:
        raise ApiError("weak_password",
                       f"Password must be at least {MIN_PASSWORD_LENGTH} characters.", 422)
    if password.lower() in {"password", "12345678", "qwertyui", "affinity"}:
        raise ApiError("weak_password", "Choose a less common password.", 422)
    return password


def token_hash(token):
    return hashlib.sha256(str(token).encode("utf-8")).hexdigest()


